const lessons=[{"sentences":[{"speaker":"A","text":"Did you finally recover from that exhausting weekend trip to the mountains?","position":1,"audioStartSeconds":0,"audioEndSeconds":4.57975},{"speaker":"B","text":"Yes although my legs still feel quite sore when I walk down stairs.","position":2,"audioStartSeconds":4.77975,"audioEndSeconds":9.114666666666666},{"speaker":"A","text":"I am not surprised because we walked nearly fifteen kilometers on Saturday alone.","position":3,"audioStartSeconds":9.314666666666668,"audioEndSeconds":14.6505},{"speaker":"B","text":"That unexpected rainstorm made the rocky paths extremely slippery too.","position":4,"audioStartSeconds":14.8505,"audioEndSeconds":19.761041666666667},{"speaker":"A","text":"We should have checked the weather forecast before booking our mountain cabin.","position":5,"audioStartSeconds":19.961041666666667,"audioEndSeconds":24.53575},{"speaker":"B","text":"At least the cozy fireplace made up for the cold wet weather.","position":6,"audioStartSeconds":24.73575,"audioEndSeconds":28.782166666666665},{"speaker":"A","text":"That is true since we spent hours drinking hot chocolate and playing cards.","position":7,"audioStartSeconds":28.982166666666668,"audioEndSeconds":33.85333333333333},{"speaker":"B","text":"What would you change if we planned another hiking trip next year?","position":8,"audioStartSeconds":34.053333333333335,"audioEndSeconds":38.08683333333333},{"speaker":"A","text":"I would definitely buy better waterproof boots before leaving home.","position":9,"audioStartSeconds":38.286833333333334,"audioEndSeconds":42.59095833333333},{"speaker":"B","text":"My old jacket also leaked water through the shoulders after twenty minutes.","position":10,"audioStartSeconds":42.790958333333336,"audioEndSeconds":47.455875},{"speaker":"A","text":"We should also pack lighter backpacks because carrying heavy gear slowed us down.","position":11,"audioStartSeconds":47.655875,"audioEndSeconds":52.8105},{"speaker":"B","text":"That is a smart idea since my shoulders hurt from all those extra snacks.","position":12,"audioStartSeconds":53.0105,"audioEndSeconds":57.830083333333334},{"speaker":"A","text":"Should we invite other friends to join us next time for more fun?","position":13,"audioStartSeconds":58.03008333333333,"audioEndSeconds":62.14091666666667},{"speaker":"B","text":"Maybe but smaller groups move faster when paths become difficult.","position":14,"audioStartSeconds":62.340916666666665,"audioEndSeconds":66.838375},{"speaker":"A","text":"Let us look at coastal towns instead of mountains for our next holiday.","position":15,"audioStartSeconds":67.038375,"audioEndSeconds":71.52291666666666},{"speaker":"B","text":"That sounds relaxing because walking on flat sandy beaches requires much less effort.","position":16,"audioStartSeconds":71.72291666666666,"audioEndSeconds":77.1095},{"speaker":"A","text":"I will search online for nice seaside cottages this weekend.","position":17,"audioStartSeconds":77.3095,"audioEndSeconds":81.386875},{"speaker":"B","text":"Send me some links whenever you find affordable options with ocean views.","position":18,"audioStartSeconds":81.586875,"audioEndSeconds":86.32970833333333}],"questions":[{"prompt":"Why were the walking paths difficult according to speaker B?","options":["An unexpected rainstorm made them slippery.","There were too many tourists blocking the way.","The local council closed the main trail."],"answer":"A","evidenceSentence":4,"evidence":"That unexpected rainstorm made the rocky paths extremely slippery too.","explanation":"Speaker B giải thích rằng cơn mưa bất ngờ đã làm cho các con đường đá trở nên trơn trượt."},{"prompt":"What does speaker A admit they forgot to do before the trip?","options":["Buy enough food for the weekend.","Check the weather forecast.","Book the mountain cabin early."],"answer":"B","evidenceSentence":5,"evidence":"We should have checked the weather forecast before booking our mountain cabin.","explanation":"Speaker A thừa nhận lẽ ra họ nên kiểm tra dự báo thời tiết trước khi đặt phòng."},{"prompt":"What is the main purpose of this conversation?","options":["To complain about a terrible hotel room.","To discuss a past trip and plan for the future.","To argue about who carried the heavy bags."],"answer":"B","evidenceSentence":8,"evidence":"What would you change if we planned another hiking trip next year?","explanation":"Hai người bạn đang nói về chuyến đi vừa qua và thảo luận những thay đổi cho chuyến đi tiếp theo."},{"prompt":"What gear does speaker A want to buy before any future trip?","options":["A stronger hiking tent.","Better waterproof boots.","A larger backpack."],"answer":"B","evidenceSentence":9,"evidence":"I would definitely buy better waterproof boots before leaving home.","explanation":"Speaker A cho biết họ chắc chắn sẽ mua những đôi bốt chống thấm nước tốt hơn."},{"prompt":"What type of holiday do they decide to consider for next time?","options":["A cultural city tour in Europe.","A relaxing coastal town visit.","A challenging jungle adventure."],"answer":"B","evidenceSentence":15,"evidence":"Let us look at coastal towns instead of mountains for our next holiday.","explanation":"Họ đồng ý xem xét các thị trấn ven biển thay vì vùng núi cho kỳ nghỉ tiếp theo."},{"prompt":"What will speaker A do this weekend?","options":["Search online for seaside cottages.","Call the mountain cabin to complain.","Buy new hiking equipment."],"answer":"A","evidenceSentence":17,"evidence":"I will search online for nice seaside cottages this weekend.","explanation":"Speaker A nói rằng họ sẽ tìm kiếm các ngôi nhà tranh ven biển trực tuyến vào cuối tuần này."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
